def make(i,prompt,opts,ans,exp,strat,steps,diff): return {"id":f"question-english-performance-2-iv-1-{i}","subject":"english","type":"single-choice","prompt":prompt,"options":[{"id":k,"text":v} for k,v in opts.items()],"knowledgeIds":[KG],"difficulty":diff,"answer":{"value":ans,"explanation":exp},"provenance":{"origin":"original","license":"All rights reserved","sourceUrl":SOURCES[0]["url"],"sourceLocator":"三份公開英文試題僅供能力方向研究；未複製原題、選項、文章或答案。","authoringNote":"依官方課綱 KG 與公開英文試題的課堂口語及詞彙產出能力方向獨立編寫；待第二輪 AI／Terra 內容複核。"},"reviewStatus":"draft","updatedAt":"2026-09-09","lessonId":LESSON,"examPatternRefs":refs(),"solutionStrategy":strat,"solutionSteps":steps}
Q=[
make(1,"A classmate speaks too softly. Which sentence should you say to ask for repetition?",{"A":"Could you say that again, please?","B":"I agree with the weather.","C":"Please spell the window.","D":"The answer is under yesterday."},"A","Could you say that again, please? directly asks the classmate to repeat the spoken message politely.","Match the communication problem, speaking too softly, with a functional request for repetition.",["Identify the problem: the message was not heard clearly.","Find the choice that requests another saying of it.","Check that please makes the request polite.","Reject the unrelated weather, window, and yesterday phrases.","Choose A and say it with rising polite intonation."],"easy"),
make(2,"Your teacher asks, 'How do you pronounce this word?' Which answer is most useful?",{"A":"It is pronounced /ˈkɒn.tɛkst/.","B":"It is next to the door.","C":"I disagree with blue.","D":"There are three pencils."},"A","The question asks for pronunciation, and the phonetic-style answer gives how the word is said.","Use the question word how and the verb pronounce to identify a pronunciation response.",["Locate the task: pronounce a word.","Look for an answer about how the word sounds.","Match the pronunciation notation with that task.","Remove location, opinion, and quantity answers.","Select A because it supplies the requested spoken form."],"easy"),
make(3,"A student needs the spelling of 'calendar.' What should the student say?",{"A":"How do you spell calendar?","B":"How do you compare calendar?","C":"Why are you a calendar?","D":"Calendar is louder than music."},"A","How do you spell calendar? is the standard question for requesting the letters in a word.","Identify the missing information as letters and choose the question form used for spelling.",["Identify the need: the student wants the letters.","Choose the verb that names writing letters: spell.","Form a polite information question with How do you.","Reject comparison, identity, and volume statements.","Choose A and check that the target word is included."],"easy"),
make(4,"The teacher asks, 'What is the answer to number six?' Which response directly answers?",{"A":"The answer is twelve.","B":"Could you repeat the question?","C":"I will compare two maps.","D":"Please describe the chair."},"A","The question asks for an answer, and The answer is twelve supplies the requested result.","Match the question's information type with a response that gives a value rather than another request.",["Find the target: number six.","Notice the teacher asks what the answer is.","Select the choice that gives a direct answer.","Reject repetition, comparison, and description requests.","Choose A and verify it responds to the exact question."],"easy"),
make(5,"A partner asks, 'What does the picture show?' Which reply describes it?",{"A":"It shows a crowded market with three bicycles.","B":"It is pronounced with two syllables.","C":"I disagree with the homework.","D":"Please repeat the final word."},"A","The reply names what appears in the picture, so it performs the requested description.","Use the object of the question, the picture's content, to distinguish describing from pronunciation or discussion moves.",["Identify the object to describe: the picture.","Look for visible people, places, or objects in a reply.","Match the market and bicycles with picture content.","Remove pronunciation, disagreement, and repetition phrases.","Select A because it gives a concrete visual description."],"medium"),
make(6,"A group has two plans for a class trip. Which sentence makes a comparison?",{"A":"The train is faster than the bus.","B":"Please spell the station.","C":"I can repeat the question.","D":"The station is near the gate."},"A","The structure faster than compares the speed of the train and the bus.","Look for two items and a comparative structure before deciding whether a sentence compares them.",["Identify the two trip options: train and bus.","Find the comparative word faster.","Notice than links the two options.","Reject spelling, repetition, and location statements.","Choose A because it compares a shared feature."],"medium"),
make(7,"A teammate says, 'This plan will save time.' You think the plan is good too. What can you say?",{"A":"I agree with you.","B":"I need you to spell it.","C":"Could you describe the clock?","D":"I disagree because I agree."},"A","I agree with you clearly expresses that the speaker has the same opinion about the plan.","Match the speaker's stated opinion with a concise agreement expression.",["Identify the teammate's opinion: the plan saves time.","Notice your opinion is the same.","Choose the phrase that signals shared agreement.","Reject spelling, description, and contradictory language.","Select A and connect it naturally to the teammate's statement."],"easy"),
make(8,"A partner says the red route is safest, but you have evidence that the blue route is safer. Which response politely disagrees?",{"A":"I see your point, but I disagree.","B":"I can spell the route.","C":"The route is a classroom.","D":"Please say the alphabet backward."},"A","I see your point, but I disagree acknowledges the partner and politely states a different view.","Use the contrast between the partner's claim and your evidence to choose a respectful disagreement.",["Identify the partner's claim about the red route.","Notice your evidence supports a different route.","Find a phrase that signals disagreement without attacking the person.","Reject spelling, nonsense, and unrelated repetition choices.","Choose A because it combines acknowledgment with disagreement."],"medium"),
make(9,"Your group cannot choose an activity. Which sentence offers a practical suggestion?",{"A":"Why don't we vote on the three ideas?","B":"The ideas are pronounced loudly.","C":"I disagree with the pencil's color.","D":"Please repeat the window."},"A","Why don't we vote ... proposes a concrete way for the group to make a decision.","Look for an utterance that suggests an action solving the stated group problem.",["Identify the problem: the group cannot choose.","Find the sentence proposing an action.","Recognize voting as a fair decision method.","Reject pronunciation, color, and window statements.","Choose A because it moves the discussion toward a decision."],"medium"),
make(10,"A visitor asks for directions, but you did not hear the street name. Which sentence should you say before answering?",{"A":"Could you repeat the street name?","B":"I agree that the street is delicious.","C":"Please compare the two lunches.","D":"The answer is twelve syllables."},"A","Asking the visitor to repeat the street name obtains the missing information needed for accurate directions.","Identify the missing part of the message and form a targeted clarification question.",["Identify what was missed: the street name.","Find the option that asks specifically for that information again.","Check that Could you makes the request polite.","Remove the unrelated agreement, comparison, and number statements.","Choose A because clarification must come before giving directions."],"hard"),
]
